CREATE TABLE `treasure_box` (
  `box_itemid` int(10) NOT NULL,
  `note` varchar(45) DEFAULT '',
  `itemid` int(10) NOT NULL,
  `note2` varchar(45) DEFAULT '',
  `count` int(10) NOT NULL DEFAULT '1',
  `enchant` int(10) NOT NULL DEFAULT '0',
  `chance` int(10) NOT NULL DEFAULT '0',
  `use_day` int(3) NOT NULL DEFAULT '0' COMMENT '可使用時間',
  `bless_change` int(3) NOT NULL DEFAULT '0',
  `unbless_change` int(3) NOT NULL DEFAULT '0',
  PRIMARY KEY (`box_itemid`,`itemid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

